package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// Color constants (ANSI escape codes)
const (
	colorReset   = "\033[0m"
	colorMagenta = "\033[95m" // for keys and non-first array elements
	colorCyan    = "\033[96m" // for values
	colorGray    = "\033[90m" // for header names
	colorGreen   = "\033[92m" // for HTTP status
	colorPurple  = "\033[95m" // same as magenta
)

// colorizeJSON colorizes a JSON value and writes it to the buffer
// parentColor is the "inherited" color for the first element of an array
func colorizeJSON(v interface{}, parentColor string, indent int, buf *bytes.Buffer) {
	indentStr := strings.Repeat("  ", indent)

	switch val := v.(type) {
	case map[string]interface{}:
		buf.WriteString("{\n")
		keys := jsonObjectKeys(v)
		for i, k := range keys {
			buf.WriteString(indentStr + "  ")
			// Key: magenta inside quotes
			buf.WriteString("\"")
			buf.WriteString(colorMagenta)
			buf.WriteString(k)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
			buf.WriteString(": ")
			// Value
			colorizeJSON(val[k], colorCyan, indent+1, buf)
			if i < len(keys)-1 {
				buf.WriteString(colorReset)
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "}")

	case []interface{}:
		buf.WriteString("[\n")
		for i, item := range val {
			buf.WriteString(indentStr + "  ")
			var elemColor string
			if i == 0 {
				elemColor = parentColor // inherit from parent context
			} else {
				buf.WriteString(colorMagenta)
				elemColor = colorMagenta
			}
			colorizeJSON(item, elemColor, indent+1, buf)
			if i < len(val)-1 {
				buf.WriteString(colorReset)
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "]")

	case string:
		if parentColor == "" || parentColor == colorReset {
			// Root context: reset before quote, reset before closing quote
			buf.WriteString(colorReset)
			buf.WriteString("\"")
			buf.WriteString(val)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
		} else {
			// Non-root context: color inside quotes
			buf.WriteString("\"")
			buf.WriteString(parentColor)
			buf.WriteString(val)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
		}

	case float64:
		if parentColor != "" && parentColor != colorReset {
			buf.WriteString(parentColor)
		}
		// Format number: if it's an integer, display without decimal point
		if val == float64(int64(val)) {
			buf.WriteString(fmt.Sprintf("%d", int64(val)))
		} else {
			buf.WriteString(fmt.Sprintf("%g", val))
		}

	case bool:
		if parentColor != "" && parentColor != colorReset {
			buf.WriteString(parentColor)
		}
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}

	case nil:
		if parentColor != "" && parentColor != colorReset {
			buf.WriteString(parentColor)
		}
		buf.WriteString("null")
	}
}

// jsonObjectKeys returns keys of a JSON object in sorted order
// (Go's JSON decoder returns a map, we need to preserve order)
func jsonObjectKeys(v interface{}) []string {
	m := v.(map[string]interface{})
	// We need the original JSON to get key order
	// This is a limitation - we'll need to use a different approach
	_ = m
	return nil
}

// ColorizeJSONBytes colorizes JSON bytes and returns the colorized string
func ColorizeJSONBytes(data []byte, pretty bool, isatty bool) string {
	if !pretty {
		// Return as-is without colorization
		return "\n" + string(data)
	}

	// Pretty-print and colorize
	var v interface{}
	if err := json.Unmarshal(data, &v); err != nil {
		// Not valid JSON, return as-is
		return "\n" + string(data)
	}

	var buf bytes.Buffer
	buf.WriteString("\n")
	if isatty {
		colorizeJSONValue(v, "", 0, &buf)
	} else {
		prettyPrintJSON(v, 0, &buf)
	}
	buf.WriteString("\n")
	return buf.String()
}

// prettyPrintJSON prints JSON without colors
func prettyPrintJSON(v interface{}, indent int, buf *bytes.Buffer) {
	indentStr := strings.Repeat("  ", indent)
	switch val := v.(type) {
	case map[string]interface{}:
		buf.WriteString("{\n")
		keys := getOrderedKeys(val)
		for i, k := range keys {
			buf.WriteString(indentStr + "  ")
			buf.WriteString("\"")
			buf.WriteString(k)
			buf.WriteString("\"")
			buf.WriteString(": ")
			prettyPrintJSON(val[k], indent+1, buf)
			if i < len(keys)-1 {
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "}")
	case []interface{}:
		buf.WriteString("[\n")
		for i, item := range val {
			buf.WriteString(indentStr + "  ")
			prettyPrintJSON(item, indent+1, buf)
			if i < len(val)-1 {
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "]")
	case string:
		data, _ := json.Marshal(val)
		buf.Write(data)
	case float64:
		if val == float64(int64(val)) {
			buf.WriteString(fmt.Sprintf("%d", int64(val)))
		} else {
			buf.WriteString(fmt.Sprintf("%g", val))
		}
	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case nil:
		buf.WriteString("null")
	}
}

// colorizeJSONValue is the main colorizer function
func colorizeJSONValue(v interface{}, parentColor string, indent int, buf *bytes.Buffer) {
	indentStr := strings.Repeat("  ", indent)
	switch val := v.(type) {
	case map[string]interface{}:
		buf.WriteString("{\n")
		keys := getOrderedKeys(val)
		for i, k := range keys {
			buf.WriteString(indentStr + "  ")
			buf.WriteString("\"")
			buf.WriteString(colorMagenta)
			buf.WriteString(k)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
			buf.WriteString(": ")
			colorizeJSONValue(val[k], colorCyan, indent+1, buf)
			if i < len(keys)-1 {
				buf.WriteString(colorReset)
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "}")
	case []interface{}:
		buf.WriteString("[\n")
		for i, item := range val {
			buf.WriteString(indentStr + "  ")
			var elemColor string
			if i == 0 {
				elemColor = parentColor
			} else {
				buf.WriteString(colorMagenta)
				elemColor = colorMagenta
			}
			colorizeJSONValue(item, elemColor, indent+1, buf)
			if i < len(val)-1 {
				buf.WriteString(colorReset)
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "]")
	case string:
		if parentColor == "" {
			// No-color context (root or first in root array)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
			buf.WriteString(val)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
		} else {
			// Colored context
			buf.WriteString("\"")
			buf.WriteString(parentColor)
			buf.WriteString(val)
			buf.WriteString(colorReset)
			buf.WriteString("\"")
		}
	case float64:
		if parentColor != "" {
			buf.WriteString(parentColor)
		}
		if val == float64(int64(val)) {
			buf.WriteString(fmt.Sprintf("%d", int64(val)))
		} else {
			buf.WriteString(fmt.Sprintf("%g", val))
		}
	case bool:
		if parentColor != "" {
			buf.WriteString(parentColor)
		}
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case nil:
		if parentColor != "" {
			buf.WriteString(parentColor)
		}
		buf.WriteString("null")
	}
}

func getOrderedKeys(m map[string]interface{}) []string {
	// Return keys sorted alphabetically (Go maps are unordered)
	// TODO: need to preserve JSON ordering
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	// Sort for consistent output
	sortStrings(keys)
	return keys
}

func sortStrings(s []string) {
	for i := 0; i < len(s); i++ {
		for j := i + 1; j < len(s); j++ {
