// OrderedMap represents a JSON object with preserved key order
type OrderedMap struct {
	Items []OrderedMapItem
}

// orderedJSONArray represents a JSON array
type orderedJSONArray []interface{}

// DecodeOrderedJSON decodes JSON while preserving object key order
func DecodeOrderedJSON(data []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return decodeValue(dec)
}

func decodeValue(dec *json.Decoder) (interface{}, error) {
	token, err := dec.Token()
	if err != nil {
		return nil, err
	}

	switch v := token.(type) {
	case json.Delim:
		switch v {
		case '{':
			return decodeObject(dec)
		case '[':
			return decodeArray(dec)
		}
	case string:
		return v, nil
	case json.Number:
		// Try integer first, then float
		if i, err := v.Int64(); err == nil {
			return float64(i), nil
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case bool:
