func runRequest(method, rawURL string, items []string) {
	// Build URL
	if !strings.Contains(rawURL, "://") {
		rawURL = "http://" + rawURL
	}

	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		log.Fatalf("bat.go:215: can't get the url %v", err)
	}

	// Parse items
	headers := map[string]string{}
	postData := map[string]string{}
	var queryParts []string

	for _, item := range items {
		if strings.Contains(item, ":") && !strings.Contains(item, "=") {
			// Header: key:value
			parts := strings.SplitN(item, ":", 2)
			if len(parts) == 2 {
				headers[strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
			}
		} else if strings.Contains(item, "==") {
			// Query string: key==value  
			parts := strings.SplitN(item, "==", 2)
			if len(parts) == 2 {
				queryParts = append(queryParts, url.QueryEscape(parts[0])+"="+url.QueryEscape("="+parts[1]))
			}
		} else if strings.Contains(item, "@") {
			// File upload: key@/path/file - skip for JSON/form mode
			// TODO: implement multipart file upload
		} else if strings.Contains(item, "=") {
			// Post data: key=value
			parts := strings.SplitN(item, "=", 2)
			if len(parts) == 2 {
				postData[parts[0]] = parts[1]
			}
		}
	}

	// Build query string
	if len(queryParts) > 0 {
		existing := parsedURL.RawQuery
		if existing != "" {
			parsedURL.RawQuery = existing + "&" + strings.Join(queryParts, "&")
		} else {
			parsedURL.RawQuery = strings.Join(queryParts, "&")
		}
	}

	// Determine method
	if method == "" {
		if len(postData) > 0 || flagBody != "" {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	// Build request body
	var bodyReader io.Reader
	var contentType string
	var bodyBytes []byte

	if flagBody != "" {
		bodyBytes = []byte(flagBody)
		bodyReader = bytes.NewReader(bodyBytes)
	} else if len(postData) > 0 {
		if flagForm {
			// Form-encoded
			formData := url.Values{}
			for k, v := range postData {
				formData.Set(k, v)
			}
			bodyBytes = []byte(formData.Encode())
			bodyReader = bytes.NewReader(bodyBytes)
			contentType = "application/x-www-form-urlencoded"
		} else {
