	output := FormatJSONBody(respBody, flagPretty, false)
	fmt.Print(output)
}

func printTTYOutput(reqDump []byte, bodyBytes []byte, resp *http.Response, respBody []byte) {
	printWhat := flagPrint
	if printWhat == "A" {
		printWhat = "HhBb"
	}

	// Print request headers
	if strings.Contains(printWhat, "H") {
		if reqDump != nil {
			// Find the boundary between headers and body in the dump
			headerEnd := bytes.Index(reqDump, []byte("\r\n\r\n"))
			var headerPart []byte
			if headerEnd >= 0 {
				headerPart = reqDump[:headerEnd+4] // include the \r\n\r\n
			} else {
				headerPart = reqDump
			}
			colorizedHeaders := colorizeRequestHeaders(headerPart)
			fmt.Print(colorizedHeaders)
		}
	}

	// Print request body
	if strings.Contains(printWhat, "B") && len(bodyBytes) > 0 {
		fmt.Print("\n")
		fmt.Print(string(bodyBytes))
		fmt.Print("\n\n")
	} else if strings.Contains(printWhat, "B") {
		fmt.Print("\n\n")
	}

	// Print response headers
	if strings.Contains(printWhat, "h") {
		colorizedRespHeaders := colorizeResponseHeaders(resp)
		fmt.Print(colorizedRespHeaders)
		fmt.Print("\n")
	}

	// Print response body
	if strings.Contains(printWhat, "b") {
		output := FormatJSONBody(respBody, flagPretty, true)
		fmt.Print(output)
	}
}
