// colorizeRequestHeaders colorizes the raw HTTP request headers dump
func colorizeRequestHeaders(dump []byte) string {
	var buf bytes.Buffer
	lines := bytes.Split(dump, []byte("\r\n"))
	for i, line := range lines {
		if len(line) == 0 {
			buf.WriteString("\r\n")
			continue
		}
		if i == 0 {
			// First line: METHOD PATH HTTP/VERSION
			parts := bytes.SplitN(line, []byte(" "), 3)
			if len(parts) == 3 {
				buf.WriteString(colorMagenta)
				buf.Write(parts[0]) // METHOD
				buf.WriteString(colorReset)
				buf.WriteString(" ")
				buf.WriteString(colorCyan)
				buf.Write(parts[1]) // PATH
				buf.WriteString(colorReset)
				buf.WriteString(" ")
				buf.WriteString(colorMagenta)
				// The version line includes trailing \r (if any)
				versionPart := parts[2]
				buf.Write(versionPart)
				buf.WriteString(colorReset)
			} else {
				buf.Write(line)
			}
		} else {
			// Header line: Name: Value
			colonIdx := bytes.IndexByte(line, ':')
			if colonIdx > 0 {
				name := line[:colonIdx]
				value := line[colonIdx+1:] // includes the space and value (with potential \r)
				buf.WriteString(colorGray)
				buf.Write(name)
				buf.WriteString(colorReset)
				buf.WriteString(":")
				buf.WriteString(colorCyan)
				buf.Write(value)
				buf.WriteString(colorReset)
			} else {
				buf.Write(line)
			}
		}
		buf.WriteString("\r\n")
	}
	return buf.String()
}

// colorizeResponseHeaders colorizes the HTTP response headers
func colorizeResponseHeaders(resp *http.Response) string {
	var buf bytes.Buffer

	// Status line
	buf.WriteString(colorMagenta)
	buf.WriteString(resp.Proto)
	buf.WriteString(colorReset)
	buf.WriteString(" ")
	buf.WriteString(colorGreen)
	buf.WriteString(resp.Status)
	buf.WriteString(colorReset)
	buf.WriteString("\r\n")

	// Headers
	for name, values := range resp.Header {
		for _, value := range values {
			buf.WriteString(colorGray)
			buf.WriteString(name)
			buf.WriteString(colorReset)
			buf.WriteString(": ")
			buf.WriteString(colorCyan)
			buf.WriteString(value)
			buf.WriteString(colorReset)
			buf.WriteString("\r\n")
		}
	}

	return buf.String()
