// ============================================================
// JSON handling with preserved key order
// ============================================================

type OrderedMap struct {
	Items []KVPair
}

type KVPair struct {
	Key   string
	Value interface{}
}

type orderedArray []interface{}

func decodeOrderedJSON(data []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return decodeJSONValue(dec)
}

func decodeJSONValue(dec *json.Decoder) (interface{}, error) {
	token, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := token.(type) {
	case json.Delim:
		switch v {
		case '{':
			return decodeJSONObject(dec)
		case '[':
			return decodeJSONArray(dec)
		}
	case string:
		return v, nil
	case json.Number:
		if i, err := v.Int64(); err == nil {
			return float64(i), nil
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case bool:
		return v, nil
	case nil:
		return nil, nil
	}
	return nil, fmt.Errorf("unexpected token")
}

func decodeJSONObject(dec *json.Decoder) (*OrderedMap, error) {
	om := &OrderedMap{}
	for {
		token, err := dec.Token()
		if err != nil {
			return nil, err
		}
		if delim, ok := token.(json.Delim); ok && delim == '}' {
			break
		}
		key, ok := token.(string)
		if !ok {
			return nil, fmt.Errorf("expected string key")
		}
		value, err := decodeJSONValue(dec)
		if err != nil {
			return nil, err
		}
		om.Items = append(om.Items, KVPair{key, value})
	}
	return om, nil
}

func decodeJSONArray(dec *json.Decoder) (orderedArray, error) {
	var arr orderedArray
	for dec.More() {
		value, err := decodeJSONValue(dec)
		if err != nil {
			return nil, err
		}
		arr = append(arr, value)
	}
	_, err := dec.Token() // consume ']'
	return arr, err
}

// renderJSON renders JSON with optional colorization
// parentColor is the inherited color for the first element of an array
func renderJSON(v interface{}, parentColor string, indent int, buf *bytes.Buffer, colorize bool) {
	indentStr := strings.Repeat("  ", indent)

	switch val := v.(type) {
	case *OrderedMap:
		buf.WriteString("{\n")
		for i, item := range val.Items {
			buf.WriteString(indentStr + "  ")
			if colorize {
				buf.WriteString("\"")
				buf.WriteString(colorMagenta)
				buf.WriteString(item.Key)
				buf.WriteString(colorReset)
				buf.WriteString("\"")
			} else {
				jsonKey, _ := json.Marshal(item.Key)
				buf.Write(jsonKey)
			}
			buf.WriteString(": ")
			var childColor string
			if colorize {
				childColor = colorCyan
			}
			renderJSON(item.Value, childColor, indent+1, buf, colorize)
			if i < len(val.Items)-1 {
				if colorize {
					buf.WriteString(colorReset)
				}
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "}")

	case orderedArray:
		buf.WriteString("[\n")
		for i, item := range val {
			buf.WriteString(indentStr + "  ")
			var elemColor string
			if i == 0 {
				// First element inherits parent color
				elemColor = parentColor
			} else {
				// Non-first elements get magenta
				if colorize {
					buf.WriteString(colorMagenta)
				}
				elemColor = colorMagenta
			}
			renderJSON(item, elemColor, indent+1, buf, colorize)
			if i < len(val)-1 {
				if colorize {
					buf.WriteString(colorReset)
				}
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(indentStr + "]")

	case string:
		if colorize {
			if parentColor == "" {
				// No-color context (root or first element in root array)
				buf.WriteString(colorReset)
				buf.WriteString("\"")
				buf.WriteString(val)
				buf.WriteString(colorReset)
				buf.WriteString("\"")
			} else {
				// Colored context: color goes inside quotes
				buf.WriteString("\"")
				buf.WriteString(parentColor)
				buf.WriteString(val)
				buf.WriteString(colorReset)
				buf.WriteString("\"")
			}
		} else {
			jsonStr, _ := json.Marshal(val)
			buf.Write(jsonStr)
		}

	case float64:
		if colorize && parentColor != "" {
			buf.WriteString(parentColor)
		}
		if val == float64(int64(val)) {
			fmt.Fprintf(buf, "%d", int64(val))
		} else {
			fmt.Fprintf(buf, "%g", val)
		}

	case bool:
		if colorize && parentColor != "" {
			buf.WriteString(parentColor)
		}
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}

	case nil:
		if colorize && parentColor != "" {
			buf.WriteString(parentColor)
		}
		buf.WriteString("null")
	}
}

func formatBody(data []byte, pretty bool, colorize bool) string {
	if len(data) == 0 {
		return "\n"
	}

	if !pretty {
		s := string(data)
		if !strings.HasSuffix(s, "\n") {
			s += "\n"
		}
		return "\n" + s
	}

	v, err := decodeOrderedJSON(data)
	if err != nil {
		// Not JSON, return as-is
		s := string(data)
		if !strings.HasSuffix(s, "\n") {
			s += "\n"
		}
		return "\n" + s
	}

	var buf bytes.Buffer
	buf.WriteString("\n")
	renderJSON(v, "", 0, &buf, colorize)
	buf.WriteString("\n")
	return buf.String()
}

// ============================================================
// Request execution
// ============================================================

func runRequest(method, rawURL string, items []string) {
	if !strings.Contains(rawURL, "://") {
		rawURL = "http://" + rawURL
	}

	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		log.Fatalf("bat.go:215: can't get the url %v", err)
	}

	// Parse items into headers and post data
	headers := map[string]string{}
	postData := map[string]string{}

	for _, item := range items {
		if strings.ContainsRune(item, '@') {
			// File upload - skip
			continue
		}
		colonIdx := strings.IndexByte(item, ':')
		eqIdx := strings.IndexByte(item, '=')
		if colonIdx > 0 && (eqIdx < 0 || colonIdx < eqIdx) {
			// Header: name:value
			headers[strings.TrimSpace(item[:colonIdx])] = strings.TrimSpace(item[colonIdx+1:])
			continue
		}
		if eqIdx > 0 {
			postData[item[:eqIdx]] = item[eqIdx+1:]
			continue
		}
	}

	// Determine method
	if method == "" {
		if len(postData) > 0 || flagBody != "" {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	// Build request body
	var bodyBytes []byte
	var contentType string

	if flagBody != "" {
		bodyBytes = []byte(flagBody)
	} else if len(postData) > 0 {
		if flagForm {
			formData := url.Values{}
			for k, v := range postData {
				formData.Set(k, v)
			}
			bodyBytes = []byte(formData.Encode())
			contentType = "application/x-www-form-urlencoded"
		} else {
			jsonBytes, err := json.Marshal(postData)
			if err != nil {
				log.Fatalf("bat.go:215: can't encode JSON: %v", err)
			}
			bodyBytes = append(jsonBytes, '\n')
			contentType = "application/json"
		}
	}

	var bodyReader io.Reader
	if len(bodyBytes) > 0 {
		bodyReader = bytes.NewReader(bodyBytes)
	}

	req, err := http.NewRequest(method, parsedURL.String(), bodyReader)
	if err != nil {
		log.Fatalf("bat.go:215: can't create request: %v", err)
	}

	req.Header.Set("User-Agent", "bat/"+Version)
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Accept-Encoding", "gzip, deflate")
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	if flagAuth != "" {
		parts := strings.SplitN(flagAuth, ":", 2)
		if len(parts) == 2 {
			req.SetBasicAuth(parts[0], parts[1])
		} else {
			req.SetBasicAuth(flagAuth, "")
		}
	}

	// Dump request (before body is consumed)
	reqDump, _ := httputil.DumpRequestOut(req, true)
	if len(bodyBytes) > 0 {
		req.Body = io.NopCloser(bytes.NewReader(bodyBytes))
	}

	// HTTP client
	transport := &http.Transport{}
	if flagInsecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if flagProxy != "" {
		if proxyURL, err := url.Parse(flagProxy); err == nil {
			transport.Proxy = http.ProxyURL(proxyURL)
		}
	}

	client := &http.Client{Transport: transport}

	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("bat.go:215: can't get the url %v", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatalf("bat.go:215: can't read response: %v", err)
	}

	isTTY := isTerminal(int(os.Stdout.Fd()))

	if flagDownload {
		handleDownload(req, resp, respBody, isTTY)
		return
	}

	if isTTY {
		printTTY(reqDump, bodyBytes, resp, respBody)
	} else {
		fmt.Print(formatBody(respBody, flagPretty, false))
	}
}

func printTTY(reqDump, bodyBytes []byte, resp *http.Response, respBody []byte) {
	printWhat := flagPrint
	if printWhat == "A" {
		printWhat = "HBhb"
	}

	showH := strings.ContainsRune(printWhat, 'H')
	showB := strings.ContainsRune(printWhat, 'B')
	showh := strings.ContainsRune(printWhat, 'h')
	showb := strings.ContainsRune(printWhat, 'b')

	// Request headers (H)
	if showH && reqDump != nil {
		// Find end of headers in dump
		headerEnd := bytes.Index(reqDump, []byte("\r\n\r\n"))
		var headerBytes []byte
		if headerEnd >= 0 {
			headerBytes = reqDump[:headerEnd+4] // include the \r\n\r\n
		} else {
			headerBytes = reqDump
		}
		fmt.Print(colorizeReqHeaders(headerBytes))
	}

	// Request body (B)
	if showB && len(bodyBytes) > 0 {
		fmt.Print("\n")
		fmt.Print(string(bodyBytes))
		fmt.Print("\n\n")
	}

	// Response headers (h)
	if showh {
		fmt.Print(colorizeRespHeaders(resp))
		fmt.Print("\n")
	}

	// Response body (b)
	if showb {
		fmt.Print(formatBody(respBody, flagPretty, true))
	}
}

// colorizeReqHeaders colorizes the request headers from the raw HTTP dump
func colorizeReqHeaders(dump []byte) string {
	var buf bytes.Buffer
	// Split by \n to preserve \r in values
	lines := bytes.Split(dump, []byte("\n"))
	for i, line := range lines {
		if len(line) == 0 {
			// End of lines (empty after final \n)
			break
		}
		if i == 0 {
			// Request line: "METHOD PATH HTTP/1.1\r"
			// Note: line has trailing \r from CRLF format
			parts := bytes.SplitN(line, []byte(" "), 3)
			if len(parts) >= 3 {
				buf.WriteString(colorMagenta)
				buf.Write(parts[0]) // METHOD
				buf.WriteString(colorReset)
				buf.WriteString(" ")
				buf.WriteString(colorCyan)
				buf.Write(parts[1]) // PATH
				buf.WriteString(colorReset)
				buf.WriteString(" ")
				buf.WriteString(colorMagenta)
				buf.Write(parts[2]) // HTTP/1.1\r (includes trailing \r)
				buf.WriteString(colorReset)
			} else {
				buf.Write(line)
			}
		} else {
			// Header line: "Name: Value\r"
			// Handle blank line (just "\r")
			colonIdx := bytes.IndexByte(line, ':')
			if colonIdx > 0 {
				name := line[:colonIdx]
				value := line[colonIdx+1:] // " Value\r"
				buf.WriteString(colorGray)
				buf.Write(name)
				buf.WriteString(colorReset)
				buf.WriteByte(':')
				buf.WriteString(colorCyan)
				buf.Write(value) // includes \r at end
				buf.WriteString(colorReset)
			} else {
				// Blank line (just "\r" or empty)
				buf.Write(line)
			}
		}
		buf.WriteString("\n")
	}
	return buf.String()
}

// colorizeRespHeaders colorizes response headers
func colorizeRespHeaders(resp *http.Response) string {
	var buf bytes.Buffer

	// Status line
	buf.WriteString(colorMagenta)
	buf.WriteString(resp.Proto)
	buf.WriteString(colorReset)
	buf.WriteString(" ")
	buf.WriteString(colorGreen)
	buf.WriteString(resp.Status)
	buf.WriteString(colorReset)
	buf.WriteString("\n")

	// Headers
	for name, values := range resp.Header {
		for _, value := range values {
			buf.WriteString(colorGray)
			buf.WriteString(name)
			buf.WriteString(colorReset)
			buf.WriteString(": ")
			buf.WriteString(colorCyan)
			buf.WriteString(value)
			buf.WriteString(colorReset)
			buf.WriteString("\n")
		}
	}

	return buf.String()
}

// ============================================================
// Download handling
// ============================================================

func handleDownload(req *http.Request, resp *http.Response, body []byte, isTTY bool) {
	filename := ""
	cd := resp.Header.Get("Content-Disposition")
	if cd != "" {
		for _, part := range strings.Split(cd, ";") {
			part = strings.TrimSpace(part)
			if strings.HasPrefix(part, "filename=") {
				filename = strings.Trim(strings.TrimPrefix(part, "filename="), "\"")
			}
		}
	}
	if filename == "" {
		filename = path.Base(req.URL.Path)
		if filename == "." || filename == "/" || filename == "" {
			filename = "index.html"
		}
	}

	if isTTY {
		fmt.Print(colorizeRespHeaders(resp))
		fmt.Print("\n")
	}

	fmt.Printf("Downloading to %q\n\n", filename)

	total := len(body)
	sizeStr := formatBytes(total)
	speed := float64(total) * 1000 // estimate

	const barWidth = 85
	bar := strings.Repeat("=", barWidth)

	fmt.Printf("\r%s / %s [%s] %.2f %% %s 0s\n",
		sizeStr, sizeStr, bar, 100.0,
		formatBytes(int(speed))+"/s")

	// Write to file
	f, err := os.Create(filename)
	if err != nil {
		log.Printf("bat.go:215: can't create file: %v", err)
		return
	}
	defer f.Close()
	f.Write(body)
}

func formatBytes(n int) string {
	switch {
	case n < 1024:
		return fmt.Sprintf("%d B", n)
	case n < 1024*1024:
		return fmt.Sprintf("%.2f KB", float64(n)/1024)
	default:
		return fmt.Sprintf("%.2f MB", float64(n)/(1024*1024))
	}
}

// ============================================================
// Benchmark mode
// ============================================================

type benchResult struct {
	duration   time.Duration
	statusCode int
	bodySize   int
	errStr     string
}

func runBench(method, rawURL string, items []string) {
	if !strings.Contains(rawURL, "://") {
		rawURL = "http://" + rawURL
	}
	if method == "" {
		method = "GET"
	}

	transport := &http.Transport{}
	if flagInsecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if flagProxy != "" {
		if proxyURL, err := url.Parse(flagProxy); err == nil {
			transport.Proxy = http.ProxyURL(proxyURL)
		}
	}

	client := &http.Client{Transport: transport}

	results := make([]benchResult, 0, flagBenchN)
	var mu sync.Mutex
	var wg sync.WaitGroup
	semaphore := make(chan struct{}, flagBenchC)

	startTime := time.Now()

	for i := 0; i < flagBenchN; i++ {
		wg.Add(1)
		semaphore <- struct{}{}
		go func() {
			defer wg.Done()
			defer func() { <-semaphore }()

			req, err := http.NewRequest(method, rawURL, nil)
			if err != nil {
				mu.Lock()
				results = append(results, benchResult{errStr: err.Error()})
				mu.Unlock()
				return
			}
			req.Header.Set("User-Agent", "bat/"+Version)
			req.Header.Set("Accept", "application/json")
			req.Header.Set("Accept-Encoding", "gzip, deflate")

			start := time.Now()
			resp, err := client.Do(req)
			elapsed := time.Since(start)

			if err != nil {
				mu.Lock()
				results = append(results, benchResult{errStr: rawURL + ": " + err.Error()})
				mu.Unlock()
				return
			}

			body, _ := io.ReadAll(resp.Body)
			resp.Body.Close()

			mu.Lock()
			results = append(results, benchResult{
				duration:   elapsed,
				statusCode: resp.StatusCode,
				bodySize:   len(body),
			})
			mu.Unlock()
		}()
	}
	wg.Wait()

	printBenchResults(results, time.Since(startTime))
}

func printBenchResults(results []benchResult, totalTime time.Duration) {
	var durations []float64
	statusCodes := map[int]int{}
	errCounts := map[string]int{}
	totalBytes := 0

	for _, r := range results {
		if r.errStr != "" {
			errCounts[r.errStr]++
		} else {
			durations = append(durations, r.duration.Seconds())
			statusCodes[r.statusCode]++
			totalBytes += r.bodySize
		}
	}

	sort.Float64s(durations)
	n := len(durations)
	total := totalTime.Seconds()

	var slowest, fastest, average, reqPerSec float64
	if n > 0 {
		slowest = durations[n-1]
		fastest = durations[0]
		sum := 0.0
		for _, d := range durations {
			sum += d
		}
		average = sum / float64(n)
		if total > 0 {
			reqPerSec = float64(n) / total
		}
	}

	fmt.Printf("\nSummary:\n")
	fmt.Printf("  Total:\t%.4f secs.\n", total)
	fmt.Printf("  Slowest:\t%.4f secs.\n", slowest)
	fmt.Printf("  Fastest:\t%.4f secs.\n", fastest)
	fmt.Printf("  Average:\t%.4f secs.\n", average)
	fmt.Printf("  Requests/sec:\t%.4f\n", reqPerSec)
	fmt.Printf("  Total Data Received:\t%d bytes.\n", totalBytes)
	if n > 0 {
		fmt.Printf("  Response Size per Request:\t%d bytes.\n", totalBytes/n)
	}

	fmt.Printf("\nStatus code distribution:\n")
	codes := make([]int, 0)
	for code := range statusCodes {
		codes = append(codes, code)
	}
	sort.Ints(codes)
	for _, code := range codes {
		fmt.Printf("  [%d]\t%d responses\n", code, statusCodes[code])
	}

	fmt.Printf("\nResponse time histogram:\n")
	if n > 0 {
		printHistogram(durations, fastest, slowest)
	}

	fmt.Printf("\nLatency distribution:\n")
	if n > 0 {
		printLatency(durations)
	}

	if len(errCounts) > 0 {
		fmt.Printf("\nError distribution:\n")
		keys := make([]string, 0)
		for k := range errCounts {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("  [%d]\t%s\n", errCounts[k], k)
		}
	}
}

func printHistogram(durations []float64, fastest, slowest float64) {
	const numBuckets = 11
	const maxBars = 40

	bucketSize := (slowest - fastest) / float64(numBuckets-1)
	if bucketSize == 0 {
		bucketSize = 0.001
	}

	counts := make([]int, numBuckets)
	for _, d := range durations {
		bucket := int((d - fastest) / bucketSize)
		if bucket >= numBuckets {
			bucket = numBuckets - 1
		}
		if bucket < 0 {
			bucket = 0
		}
		counts[bucket]++
	}

	maxCount := 0
	for _, c := range counts {
		if c > maxCount {
			maxCount = c
		}
	}

	for i := 0; i < numBuckets; i++ {
		bucketStart := fastest + float64(i)*bucketSize
		bars := 0
		if maxCount > 0 {
			bars = int(math.Round(float64(counts[i]) / float64(maxCount) * maxBars))
		}
		fmt.Printf("  %.3f [%d]\t|%s\n", bucketStart, counts[i], strings.Repeat("∎", bars))
	}
}

func printLatency(durations []float64) {
	n := len(durations)
	type pEntry struct {
		label int
		frac  float64
	}
	pctls := []pEntry{
		{10, 0.10}, {25, 0.25}, {50, 0.50}, {75, 0.75},
		{90, 0.90}, {95, 0.95}, {99, 0.99},
	}
	for _, p := range pctls {
		idx := int(math.Ceil(float64(n) * p.frac))
		if idx < n {
			fmt.Printf("  %d%% in %.4f secs.\n", p.label, durations[idx])
		}
	}
}
