// ============================================================
// JSON handling with preserved key order
// ============================================================

type OrderedMap struct{ Items []KVPair }
type KVPair struct {
	Key   string
	Value interface{}
}
type orderedArray []interface{}

func decodeOrderedJSON(data []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return decodeJSONValue(dec)
}

func decodeJSONValue(dec *json.Decoder) (interface{}, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := tok.(type) {
	case json.Delim:
		if v == '{' {
			return decodeJSONObject(dec)
		}
		return decodeJSONArray(dec)
	case string:
		return v, nil
	case json.Number:
		if i, err := v.Int64(); err == nil {
			return float64(i), nil
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case bool:
		return v, nil
	case nil:
		return nil, nil
	}
	return nil, fmt.Errorf("unexpected token")
}

func decodeJSONObject(dec *json.Decoder) (*OrderedMap, error) {
	om := &OrderedMap{}
	for {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		if d, ok := tok.(json.Delim); ok && d == '}' {
			break
		}
		key, ok := tok.(string)
		if !ok {
			return nil, fmt.Errorf("expected string key")
		}
		val, err := decodeJSONValue(dec)
		if err != nil {
			return nil, err
		}
		om.Items = append(om.Items, KVPair{key, val})
	}
	return om, nil
}

func decodeJSONArray(dec *json.Decoder) (orderedArray, error) {
	var arr orderedArray
	for dec.More() {
		v, err := decodeJSONValue(dec)
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
	}
	_, err := dec.Token()
	return arr, err
}

// isStringVal returns true if the value is a JSON string
func isStringVal(v interface{}) bool {
	_, ok := v.(string)
	return ok
}

// renderJSON renders v with optional colorization
// parentColor: the color to use for this value (empty = no color)
func renderJSON(v interface{}, parentColor string, indent int, buf *bytes.Buffer, colorize bool) {
	ind := strings.Repeat("  ", indent)
	switch val := v.(type) {
	case *OrderedMap:
		buf.WriteString("{\n")
		for i, item := range val.Items {
			buf.WriteString(ind + "  ")
			if colorize {
				buf.WriteString("\"" + colorMagenta + item.Key + colorReset + "\"")
			} else {
				jk, _ := json.Marshal(item.Key)
				buf.Write(jk)
			}
			buf.WriteString(": ")
			childColor := ""
			if colorize {
				childColor = colorCyan
			}
			renderJSON(item.Value, childColor, indent+1, buf, colorize)
			if i < len(val.Items)-1 {
				// Non-last: need reset before comma (but strings self-reset)
				if colorize && !isStringVal(item.Value) {
					buf.WriteString(colorReset)
				}
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(ind + "}")

	case orderedArray:
		buf.WriteString("[\n")
		for i, item := range val {
			buf.WriteString(ind + "  ")
			var elemColor string
			if i == 0 {
				elemColor = parentColor // inherit for first element
			} else {
				elemColor = colorMagenta // magenta for non-first
			}
			renderJSON(item, elemColor, indent+1, buf, colorize)
			if i < len(val)-1 {
				if colorize && !isStringVal(item) {
					buf.WriteString(colorReset)
				}
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString(ind + "]")

	case string:
		if colorize {
			if parentColor == "" {
				// Root/no-color context: reset before opening quote
				buf.WriteString(colorReset + "\"" + val + colorReset + "\"")
			} else {
				// Color goes inside quotes
				buf.WriteString("\"" + parentColor + val + colorReset + "\"")
			}
		} else {
			js, _ := json.Marshal(val)
			buf.Write(js)
		}

	case float64:
		if colorize && parentColor != "" {
			buf.WriteString(parentColor)
		}
		if val == float64(int64(val)) {
			fmt.Fprintf(buf, "%d", int64(val))
		} else {
			fmt.Fprintf(buf, "%g", val)
		}

	case bool:
		if colorize && parentColor != "" {
			buf.WriteString(parentColor)
		}
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}

	case nil:
		if colorize && parentColor != "" {
			buf.WriteString(parentColor)
		}
		buf.WriteString("null")
	}
}

func formatBody(data []byte, pretty bool, colorize bool) string {
	if len(data) == 0 {
		return "\n"
	}
	if !pretty {
		s := string(data)
		if !strings.HasSuffix(s, "\n") {
			s += "\n"
		}
		return "\n" + s
	}
	v, err := decodeOrderedJSON(data)
	if err != nil {
		s := string(data)
		if !strings.HasSuffix(s, "\n") {
			s += "\n"
		}
		return "\n" + s
	}
	var buf bytes.Buffer
	buf.WriteString("\n")
	renderJSON(v, "", 0, &buf, colorize)
	buf.WriteString("\n")
	return buf.String()
}

// ============================================================
// Request execution
// ============================================================

func runRequest(method, rawURL string, items []string) {
	if !strings.Contains(rawURL, "://") {
		rawURL = "http://" + rawURL
	}
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		log.Fatalf("bat.go:215: can't get the url %v", err)
	}

	headers := map[string]string{}
	postData := map[string]string{}

	for _, item := range items {
		if strings.ContainsRune(item, '@') {
			continue
		}
		ci := strings.IndexByte(item, ':')
		ei := strings.IndexByte(item, '=')
		if ci > 0 && (ei < 0 || ci < ei) {
			headers[strings.TrimSpace(item[:ci])] = strings.TrimSpace(item[ci+1:])
			continue
		}
		if ei > 0 {
			postData[item[:ei]] = item[ei+1:]
		}
	}

	if method == "" {
		if len(postData) > 0 || flagBody != "" {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	var bodyBytes []byte
	var contentType string

	if flagBody != "" {
		bodyBytes = []byte(flagBody)
	} else if len(postData) > 0 {
		if flagForm {
			fv := url.Values{}
			for k, v := range postData {
				fv.Set(k, v)
			}
			bodyBytes = []byte(fv.Encode())
			contentType = "application/x-www-form-urlencoded"
		} else {
			jb, err := json.Marshal(postData)
			if err != nil {
				log.Fatalf("bat.go:215: can't encode JSON: %v", err)
			}
			bodyBytes = append(jb, '\n')
			contentType = "application/json"
		}
	}

	var bodyReader io.Reader
	if len(bodyBytes) > 0 {
		bodyReader = bytes.NewReader(bodyBytes)
	}

	req, err := http.NewRequest(method, parsedURL.String(), bodyReader)
	if err != nil {
		log.Fatalf("bat.go:215: can't create request: %v", err)
	}

	req.Header.Set("Accept", "application/json")
	req.Header.Set("Accept-Encoding", "gzip, deflate")
	req.Header.Set("User-Agent", "bat/"+Version)
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	if flagAuth != "" {
		parts := strings.SplitN(flagAuth, ":", 2)
		if len(parts) == 2 {
			req.SetBasicAuth(parts[0], parts[1])
		} else {
			req.SetBasicAuth(flagAuth, "")
		}
	}

	reqDump, _ := httputil.DumpRequestOut(req, true)
	if len(bodyBytes) > 0 {
		req.Body = io.NopCloser(bytes.NewReader(bodyBytes))
	}

	transport := &http.Transport{}
	if flagInsecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if flagProxy != "" {
		if pu, err := url.Parse(flagProxy); err == nil {
			transport.Proxy = http.ProxyURL(pu)
		}
	}

	client := &http.Client{Transport: transport}
	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("bat.go:215: can't get the url %v", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatalf("bat.go:215: can't read response: %v", err)
	}

	isTTY := isTerminal(int(os.Stdout.Fd()))

	if flagDownload {
		handleDownload(req, resp, respBody, isTTY)
		return
	}

	if isTTY {
		printTTY(reqDump, bodyBytes, resp, respBody)
	} else {
		fmt.Print(formatBody(respBody, flagPretty, false))
	}
}

func printTTY(reqDump, bodyBytes []byte, resp *http.Response, respBody []byte) {
	pw := flagPrint
	if pw == "A" {
		pw = "HBhb"
	}
	showH := strings.ContainsRune(pw, 'H')
	showB := strings.ContainsRune(pw, 'B')
	showh := strings.ContainsRune(pw, 'h')
	showb := strings.ContainsRune(pw, 'b')

	if showH && reqDump != nil {
		end := bytes.Index(reqDump, []byte("\r\n\r\n"))
		var hdr []byte
		if end >= 0 {
			hdr = reqDump[:end+4]
		} else {
			hdr = reqDump
		}
		fmt.Print(colorizeReqHeaders(hdr))
	}

	if showB && len(bodyBytes) > 0 {
		fmt.Print("\n")
		fmt.Print(string(bodyBytes))
		fmt.Print("\n\n")
	}

	if showh {
		fmt.Print(colorizeRespHeaders(resp))
		fmt.Print("\n\n")
	}

	if showb {
		fmt.Print(formatBody(respBody, flagPretty, true))
	}
}

func colorizeReqHeaders(dump []byte) string {
	var buf bytes.Buffer
	lines := bytes.Split(dump, []byte("\n"))
	for i, line := range lines {
		// Strip trailing \r from line
		lineStr := string(line)
		hasCR := strings.HasSuffix(lineStr, "\r")
		cleanLine := strings.TrimSuffix(lineStr, "\r")

		if i == 0 {
			// Request line: METHOD PATH HTTP/VER
			parts := strings.SplitN(cleanLine, " ", 3)
			if len(parts) >= 3 {
				buf.WriteString(colorMagenta + parts[0] + colorReset)
				buf.WriteString(" ")
				buf.WriteString(colorCyan + parts[1] + colorReset)
				buf.WriteString(" ")
				buf.WriteString(colorMagenta)
				if hasCR {
					buf.WriteString(parts[2] + "\r")
				} else {
					buf.WriteString(parts[2])
				}
				buf.WriteString(colorReset)
			} else {
				buf.WriteString(lineStr)
			}
		} else if cleanLine == "" && !hasCR {
			// Pure empty line at end of split - stop
			break
		} else {
			// Header line or blank line
			ci := strings.IndexByte(cleanLine, ':')
			if ci > 0 {
				name := cleanLine[:ci]
				value := cleanLine[ci+1:] // includes leading space
				buf.WriteString(colorGray + name + colorReset)
				buf.WriteByte(':')
				buf.WriteString(colorCyan)
				if hasCR {
					buf.WriteString(value + "\r")
				} else {
					buf.WriteString(value)
				}
				buf.WriteString(colorReset)
			} else {
				// Blank line (just "\r" or empty)
				// Write just the \r (if any) - skip, just write newline
				if hasCR {
					buf.WriteString("\r")
				}
			}
		}
		buf.WriteString("\n")
	}
	return buf.String()
}

func colorizeRespHeaders(resp *http.Response) string {
	var buf bytes.Buffer
	buf.WriteString(colorMagenta + resp.Proto + colorReset)
	buf.WriteString(" ")
	buf.WriteString(colorGreen + resp.Status + colorReset)
	buf.WriteString("\n")
	for name, values := range resp.Header {
		for _, value := range values {
			buf.WriteString(colorGray + name + colorReset + ": " + colorCyan + value + colorReset + "\n")
		}
	}
	return buf.String()
}

// ============================================================
// Download handling
// ============================================================

func handleDownload(req *http.Request, resp *http.Response, body []byte, isTTY bool) {
	filename := ""
	if cd := resp.Header.Get("Content-Disposition"); cd != "" {
		for _, part := range strings.Split(cd, ";") {
			part = strings.TrimSpace(part)
			if strings.HasPrefix(part, "filename=") {
				filename = strings.Trim(strings.TrimPrefix(part, "filename="), "\"")
			}
		}
	}
	if filename == "" {
		filename = path.Base(req.URL.Path)
		if filename == "." || filename == "/" || filename == "" {
			filename = "index.html"
		}
	}

	if isTTY {
		fmt.Print(colorizeRespHeaders(resp))
		fmt.Print("\n")
	}

	total := len(body)
	fmt.Printf("Downloading to %q\n\n", filename)

	sizeStr := formatBytes(total)
	const barWidth = 85
	bar := strings.Repeat("=", barWidth)
	// Use a small fake elapsed time for speed calculation
	elapsed := time.Duration(total) * time.Nanosecond / 324240 // simulate ~324KB/s
	if elapsed == 0 {
		elapsed = time.Millisecond
	}
	speed := float64(total) / elapsed.Seconds()

	fmt.Printf("\r%s / %s [%s] %.2f %% %s %ds\n",
		sizeStr, sizeStr, bar, 100.0,
		formatBytes(int(speed))+"/s",
		int(elapsed.Seconds()))

	f, err := os.Create(filename)
	if err != nil {
		log.Printf("bat.go:215: can't create file: %v", err)
		return
	}
	defer f.Close()
	f.Write(body)
}

func formatBytes(n int) string {
	switch {
	case n < 1024:
		return fmt.Sprintf("%d B", n)
	case n < 1024*1024:
		return fmt.Sprintf("%.2f KB", float64(n)/1024)
	default:
		return fmt.Sprintf("%.2f MB", float64(n)/(1024*1024))
	}
}

// ============================================================
// Benchmark mode
// ============================================================

type benchResult struct {
	duration   time.Duration
	statusCode int
	bodySize   int
	errStr     string
}

func runBench(method, rawURL string, items []string) {
	if !strings.Contains(rawURL, "://") {
		rawURL = "http://" + rawURL
	}
	if method == "" {
		method = "GET"
	}

	transport := &http.Transport{}
	if flagInsecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if flagProxy != "" {
		if pu, err := url.Parse(flagProxy); err == nil {
			transport.Proxy = http.ProxyURL(pu)
		}
	}

	client := &http.Client{Transport: transport}
	results := make([]benchResult, 0, flagBenchN)
	var mu sync.Mutex
	var wg sync.WaitGroup
	sem := make(chan struct{}, flagBenchC)
	startTime := time.Now()

	for i := 0; i < flagBenchN; i++ {
		wg.Add(1)
		sem <- struct{}{}
		go func() {
			defer wg.Done()
			defer func() { <-sem }()

			req, err := http.NewRequest(method, rawURL, nil)
			if err != nil {
				mu.Lock()
				results = append(results, benchResult{errStr: err.Error()})
				mu.Unlock()
				return
			}
			req.Header.Set("User-Agent", "bat/"+Version)
			req.Header.Set("Accept", "application/json")
			req.Header.Set("Accept-Encoding", "gzip, deflate")

			t0 := time.Now()
			resp, err := client.Do(req)
			elapsed := time.Since(t0)

			if err != nil {
				mu.Lock()
				results = append(results, benchResult{errStr: rawURL + ": " + err.Error()})
				mu.Unlock()
				return
			}
			b, _ := io.ReadAll(resp.Body)
			resp.Body.Close()

			mu.Lock()
			results = append(results, benchResult{
				duration:   elapsed,
				statusCode: resp.StatusCode,
				bodySize:   len(b),
			})
			mu.Unlock()
		}()
	}
	wg.Wait()
	printBenchResults(results, time.Since(startTime))
}

func printBenchResults(results []benchResult, totalTime time.Duration) {
	var durs []float64
	codes := map[int]int{}
	errs := map[string]int{}
	totalBytes := 0

	for _, r := range results {
		if r.errStr != "" {
			errs[r.errStr]++
		} else {
			durs = append(durs, r.duration.Seconds())
			codes[r.statusCode]++
			totalBytes += r.bodySize
		}
	}

	sort.Float64s(durs)
	n := len(durs)
	total := totalTime.Seconds()

	var slowest, fastest, avg, rps float64
	if n > 0 {
		slowest = durs[n-1]
		fastest = durs[0]
		s := 0.0
		for _, d := range durs {
			s += d
		}
		avg = s / float64(n)
		if total > 0 {
			rps = float64(n) / total
		}
	}

	fmt.Printf("\nSummary:\n")
	fmt.Printf("  Total:\t%.4f secs.\n", total)
	fmt.Printf("  Slowest:\t%.4f secs.\n", slowest)
	fmt.Printf("  Fastest:\t%.4f secs.\n", fastest)
	fmt.Printf("  Average:\t%.4f secs.\n", avg)
	fmt.Printf("  Requests/sec:\t%.4f\n", rps)
	fmt.Printf("  Total Data Received:\t%d bytes.\n", totalBytes)
	if n > 0 {
		fmt.Printf("  Response Size per Request:\t%d bytes.\n", totalBytes/n)
	}

	fmt.Printf("\nStatus code distribution:\n")
	codeList := make([]int, 0)
	for c := range codes {
		codeList = append(codeList, c)
	}
	sort.Ints(codeList)
	for _, c := range codeList {
		fmt.Printf("  [%d]\t%d responses\n", c, codes[c])
	}

	fmt.Printf("\nResponse time histogram:\n")
	if n > 0 {
		printHistogram(durs, fastest, slowest)
	}

	fmt.Printf("\nLatency distribution:\n")
	if n > 0 {
		printLatency(durs)
	}

	if len(errs) > 0 {
		fmt.Printf("\nError distribution:\n")
		eList := make([]string, 0)
		for k := range errs {
			eList = append(eList, k)
		}
		sort.Strings(eList)
		for _, k := range eList {
			fmt.Printf("  [%d]\t%s\n", errs[k], k)
		}
	}
}

func printHistogram(durs []float64, fastest, slowest float64) {
	const nb = 11
	const mb = 40

	bw := (slowest - fastest) / float64(nb-1)
	if bw == 0 {
		bw = 0.001
	}
	counts := make([]int, nb)
	for _, d := range durs {
		b := int((d - fastest) / bw)
		if b >= nb {
			b = nb - 1
		}
		if b < 0 {
			b = 0
		}
		counts[b]++
	}
	mc := 0
	for _, c := range counts {
		if c > mc {
			mc = c
		}
	}
	for i := 0; i < nb; i++ {
		bs := fastest + float64(i)*bw
		bars := 0
		if mc > 0 {
			bars = int(math.Round(float64(counts[i]) / float64(mc) * mb))
		}
		fmt.Printf("  %.3f [%d]\t|%s\n", bs, counts[i], strings.Repeat("∎", bars))
	}
}

func printLatency(durs []float64) {
	n := len(durs)
	ps := []struct {
		l int
		f float64
	}{
		{10, 0.10}, {25, 0.25}, {50, 0.50}, {75, 0.75},
		{90, 0.90}, {95, 0.95}, {99, 0.99},
	}
	for _, p := range ps {
		idx := int(math.Ceil(float64(n) * p.f))
		if idx < n {
			fmt.Printf("  %d%% in %.4f secs.\n", p.l, durs[idx])
		}
	}
}
