new_func = '''func colorizeReqHeaders(dump []byte) string {
	var buf bytes.Buffer
	lines := bytes.Split(dump, []byte("\\n"))
	if len(lines) == 0 {
		return ""
	}

	// Parse the request line (line 0)
	line0 := string(lines[0])
	hasCR0 := strings.HasSuffix(line0, "\\r")
	cleanLine0 := strings.TrimSuffix(line0, "\\r")
	parts := strings.SplitN(cleanLine0, " ", 3)
	if len(parts) >= 3 {
		buf.WriteString(colorMagenta + parts[0] + colorReset)
		buf.WriteString(" ")
		buf.WriteString(colorCyan + parts[1] + colorReset)
		buf.WriteString(" ")
		buf.WriteString(colorMagenta)
		if hasCR0 {
			buf.WriteString(parts[2] + "\\r")
		} else {
			buf.WriteString(parts[2])
		}
		buf.WriteString(colorReset)
	} else {
		buf.WriteString(line0)
	}
	buf.WriteString("\\n")

	// Parse all headers and sort them alphabetically
	type headerLine struct {
		name  string
		value string
		full  string // original line for non-header lines
	}
	var headers []headerLine

	for _, line := range lines[1:] {
		lineStr := string(line)
		hasCR := strings.HasSuffix(lineStr, "\\r")
		cleanLine := strings.TrimSuffix(lineStr, "\\r")

		if cleanLine == "" && !hasCR {
			break // end of headers
		}

		ci := strings.IndexByte(cleanLine, ':')
		if ci > 0 {
			name := cleanLine[:ci]
			value := cleanLine[ci+1:]
			valueWithCR := value
			if hasCR {
				valueWithCR = value + "\\r"
			}
			headers = append(headers, headerLine{name: name, value: valueWithCR})
		} else {
			// Blank line or non-header
			headers = append(headers, headerLine{full: lineStr})
		}
	}

	// Sort headers alphabetically by name
	for i := 0; i < len(headers); i++ {
		for j := i + 1; j < len(headers); j++ {
			if headers[i].name != "" && headers[j].name != "" &&
				headers[i].name > headers[j].name {
				headers[i], headers[j] = headers[j], headers[i]
			}
		}
	}

	// Write sorted headers
	for _, h := range headers {
		if h.name == "" {
			// blank line
		} else {
			buf.WriteString(colorGray + h.name + colorReset)
			buf.WriteByte(':')
			buf.WriteString(colorCyan + h.value + colorReset)
		}
		buf.WriteString("\\n")
	}

	return buf.String()
}'''

